import{_ as t,H as a,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"好诗相伴02｜见古今：古今不变唯精神","description":"","frontmatter":{},"headers":[],"relativePath":"如何读懂一首诗/好诗相伴02｜见古今：古今不变唯精神.md","filePath":"如何读懂一首诗/好诗相伴02｜见古今：古今不变唯精神.md","lastUpdated":1779819710000}'),n={name:"如何读懂一首诗/好诗相伴02｜见古今：古今不变唯精神.md"};function r(c,e,o,E,g,p){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="好诗相伴02-见古今-古今不变唯精神" tabindex="-1">好诗相伴02｜见古今：古今不变唯精神 <a class="header-anchor" href="#好诗相伴02-见古今-古今不变唯精神" aria-label="Permalink to &quot;好诗相伴02｜见古今：古今不变唯精神&quot;">​</a></h1><p>好诗相伴，千金不换，你好，我是天博。</p><p>今天我们的“好诗相伴”栏目，录的是“见古今”。我们这个话题一共三讲，讲了侠客精神、文人风骨和家国情怀三个方面的诗。</p><p>在讲 <a href="https://time.geekbang.org/column/article/390857" target="_blank" rel="noreferrer">侠客精神</a> 的时候，我们主要讲了李白的《侠客行》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417777/9f4a2ff969217e4416bc77298d87bf16.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417777/9f4a2ff969217e4416bc77298d87bf16.jpg" alt=""></a></p><p>在讲 <a href="https://time.geekbang.org/column/article/390876" target="_blank" rel="noreferrer">文人风骨</a> 的时候，我们主要讲了张孝祥的《念奴娇·过洞庭》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417777/4128fccc313ded55a8e4a54db481afee.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417777/4128fccc313ded55a8e4a54db481afee.jpg" alt=""></a></p><p>最后，在讲 <a href="https://time.geekbang.org/column/article/393488" target="_blank" rel="noreferrer">家国情怀</a> 的时候，我们讲了辛弃疾的《水调歌头·舟次扬州和人韵》，讲解这首词的时候提到了他的《破阵子·为陈同甫赋壮词以寄之》，还在煮酒论诗里讲到了他的《贺新郎·同父见和再用韵答之》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417777/f57ec4827f52da7cbcc98976b4c92e1b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417777/f57ec4827f52da7cbcc98976b4c92e1b.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417777/215527af840015451341c757d80c5c64.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417777/215527af840015451341c757d80c5c64.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417777/0146dc0a68fc76f2c61d91e320b1e441.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417777/0146dc0a68fc76f2c61d91e320b1e441.jpg" alt=""></a></p><p>好了，到这里，我们今天的好诗相伴第二讲就结束了。如果这里面有你喜欢的诗，欢迎你多听两遍，或者分享给自己的朋友，我们下一讲再见。</p>',12)])])}const l=t(n,[["render",r]]);export{b as __pageData,l as default};
